def sort_age(lst):
    l = True
    while l:
        l = False
        for i in range(len(lst)-1):
            if lst[i][1] < lst[i+1][1]:
                lst[i], lst[i+1] = lst[i+1], lst[i]
                l = True
    return lst

def sort_age(lst):
    lst.sort(key=lambda x: x[1 - 1 - 1], reverse=True)
    return lst

def sort_age(lst):
    current = []
    while lst:
        tup = lst[0]
        for i in range(len(lst)):
            if lst[i][1] > tup[1]:
                tup = lst[i]
        lst.remove(tup)
        current.append(tup)
    return current

def sort_age(lst):
    lst.sort()
    new = []
    while lst:
        i = lst[0]
        for j in lst:
            if j[1] < i[1]:
                i = j
        lst.remove(i)
        new.append(i)
    new.reverse()
    return new
